commands:
pwsh -NoProfile -Command "
Import-Module Pode -MaximumVersion 2.99.99 -Force
(Get-Command Write-PodeTextResponse).Parameters.Keys -contains 'ContentType' | ForEach-Object { Write-Host ('Write-PodeTextResponse has -ContentType: ' + \$_) }
Get-Command Add-PodeHeader -ErrorAction SilentlyContinue | ForEach-Object { Write-Host ('Add-PodeHeader exists: ' + \$_.Name) }
Get-Command Set-PodeResponseAttachment -ErrorAction SilentlyContinue | ForEach-Object { Write-Host ('Set-PodeResponseAttachment exists: ' + \$_.Name) }
"
